def solve(inp):
    h,w=len(inp),len(inp[0])
    # stripes: collect (offset, color) for each direction; choose direction where single-occurrence colors are constant
    best=None
    for name,off in (('d',lambda i,j:j-i),('a',lambda i,j:i+j)):
        from collections import defaultdict
        m=defaultdict(set)
        for i in range(h):
            for j in range(w):
                if inp[i][j]: m[inp[i][j]].add(off(i,j))
        ok=sum(1 for v,s in m.items() if len(s)==1)
        if best is None or ok>best[0]: best=(ok,name,off,m)
    _,name,off,m=best
    # stripe list: (offset, color); multi-stripe colors contribute several
    stripes=[]
    for v,s in m.items():
        for o in s: stripes.append((o,v))
    n=len(stripes)
    p=None; pat=None
    for cand in range(n, 2*n+1):
        res=[o%cand for o,_ in stripes]
        if len(set(res))==n:
            p=cand; pat=[0]*p
            for o,v in stripes: pat[o%p]=v
            break
    if name=='d':
        return [[pat[(j-i)%p] for j in range(w)] for i in range(h)]
    else:
        return [[pat[(i+j)%p] for j in range(w)] for i in range(h)]
