def stripes_diagonals(grid):
    """Return (direction, [(offset, color), ...]) for the grid\'s diagonal stripes, choosing the direction (\'d\': j-i, \'a\': i+j) in which the most single-stripe colors have constant offset."""
    from collections import defaultdict
    h, w = len(grid), len(grid[0])
    best = None
    for name, off in ((\'d\', lambda i, j: j - i), (\'a\', lambda i, j: i + j)):
        m = defaultdict(set)
        for i in range(h):
            for j in range(w):
                if grid[i][j]:
                    m[grid[i][j]].add(off(i, j))
        ok = sum(1 for v, s in m.items() if len(s) == 1)
        if best is None or ok > best[0]:
            best = (ok, name, off, m)
    _, name, off, m = best
    return name, [(o, v) for v, s in m.items() for o in s]

def diagonal_period_pattern(stripes):
    """The smallest period p (>= number of stripes) making all stripe offsets distinct mod p, and the length-p pattern of stripe colors by residue."""
    n = len(stripes)
    for p in range(n, 2 * n + 1):
        if len({o % p for o, _ in stripes}) == n:
            pat = [0] * p
            for o, v in stripes:
                pat[o % p] = v
            return p, pat
    raise ValueError("no period found")

def fill_diagonal_periodic(grid, direction, p, pat):
    """Every cell filled with pat[offset mod p], offset = j-i (\'d\') or i+j (\'a\')."""
    h, w = len(grid), len(grid[0])
    if direction == \'d\':
        return [[pat[(j - i) % p] for j in range(w)] for i in range(h)]
    return [[pat[(i + j) % p] for j in range(w)] for i in range(h)]
